function FeatureHeader({ copy, action, onAction }: { copy: typeof pageCopy[string]; action?: string; onAction?: () => void }) {
  return <section className="feature-hero"><div><div className="eyebrow feature-eyebrow"><span className="feature-eyebrow-icon"><Icon name={copy.icon} size={14} /></span>{copy.eyebrow}</div><h1>{copy.title}</h1><p>{copy.body}</p></div>{action ? <button className="button button-primary button-with-icon" onClick={onAction}><Icon name="plus" size={16} /> {action}</button> : null}</section>;
}

function FilterChip({ active, children, onClick }: { active: boolean; children: React.ReactNode; onClick: () => void }) {
  return <button className={`filter-chip ${active ? "filter-chip-active" : ""}`} onClick={onClick}>{children}</button>;
}

function EmptyState({ icon, title, body, href, action }: { icon: string; title: string; body: string; href?: string; action?: string }) {
  return <div className="empty-state"><div className="empty-state-icon"><Icon name={icon} size={22} /></div><h3>{title}</h3><p>{body}</p>{href && action ? <Link href={href as Route} className="button button-primary">{action}<Icon name="arrow-right" size={14} /></Link> : null}</div>;
}

function isDirectPdf(source?: string | null): boolean {
  return Boolean(source && /\.pdf(?:$|[?#])/i.test(source));
}

type OfficialMaterialGroup = { subject: string; modules: ResourceItem[] };

function ResourceTile({
  resource,
  onBookmark,
  onComplete,
}: {
  resource: ResourceItem;
  onBookmark: (resource: ResourceItem) => void;
  onComplete: (resource: ResourceItem) => void;
}) {
  return <article className="resource-card"><div className="resource-card-top"><div className="resource-file-icon"><Icon name="file-text" size={20} /></div><button className={`icon-button ${resource.bookmarked ? "icon-button-active" : ""}`} onClick={() => onBookmark(resource)} aria-label={resource.bookmarked ? "Remove bookmark" : "Bookmark resource"}><Icon name="bookmark" size={16} /></button></div><div className="resource-card-body"><div className="resource-type-line"><span>{resource.level}</span><span>{resource.resource_type}</span>{resource.official_icai ? <span className="official-badge">Official source</span> : null}</div><h3>{resource.title}</h3><p>{resource.subject}{resource.chapter ? ` · ${resource.chapter}` : ""}</p></div><div className="resource-card-footer"><span>{resource.file_name ?? resource.attempt ?? "Resource"}</span><div className="resource-card-actions">{resource.file_name || resource.source ? <button onClick={() => window.open(`${API_BASE_URL}/api/v1/resources/${resource.id}/download`, "_blank", "noopener,noreferrer")}><Icon name={resource.source && !resource.file_name ? "arrow-up-right" : "download"} size={13} /> {resource.source && !resource.file_name ? "Open official source" : "Download"}</button> : null}<button className={resource.completed ? "completed-action" : ""} onClick={() => onComplete(resource)}>{resource.completed ? <><Icon name="check" size={13} /> Completed</> : "Mark complete"}</button></div></div></article>;
}

function OfficialMaterialTile({ group, onOpen }: { group: OfficialMaterialGroup; onOpen: () => void }) {
  const directPdfCount = group.modules.filter((resource) => isDirectPdf(resource.source)).length;
  return <article className="resource-card official-material-tile"><div className="resource-card-top"><div className="resource-file-icon"><Icon name="book-open" size={20} /></div><span className="official-badge">Latest ICAI</span></div><div className="resource-card-body"><div className="resource-type-line"><span>Official study material</span><span>{group.modules.length} tiles</span></div><h3>{group.subject}</h3><p>Chapter-wise modules and units{directPdfCount ? ` · ${directPdfCount} PDFs ready in app` : ""}</p></div><div className="resource-card-footer"><span>ICAI source links</span><button onClick={onOpen}>View modules <Icon name="arrow-right" size={13} /></button></div></article>;
}

function ResourceWorkspace({ view = "resources" }: { view?: "resources" | "past-papers" | "library" }) {
  const [resources, setResources] = useState<ResourceItem[]>([]);
  const [query, setQuery] = useState("");
  const [type, setType] = useState("All");
  const [subject, setSubject] = useState("All");
  const [chapter, setChapter] = useState("All");
  const [selectedSubject, setSelectedSubject] = useState<string | null>(null);
  const [openModule, setOpenModule] = useState<ResourceItem | null>(null);
  const [loading, setLoading] = useState(true);
  const [notice, setNotice] = useState<string | null>(null);

  useEffect(() => {
    apiFetch<ResourceItem[]>("/api/v1/resources").then(setResources).catch(() => setResources([])).finally(() => setLoading(false));
  }, []);

  const types = ["All", ...Array.from(new Set(resources.map((resource) => resource.resource_type)))];
  const subjects = ["All", ...Array.from(new Set(resources.map((resource) => resource.subject)))];
  const chapters = ["All", ...Array.from(new Set(resources.filter((resource) => subject === "All" || resource.subject === subject).map((resource) => resource.chapter).filter((value): value is string => Boolean(value))))];
  const scopedResources = view === "past-papers" ? resources.filter((resource) => /PYQ|past|paper/i.test(`${resource.resource_type} ${resource.title}`)) : view === "library" ? resources.filter((resource) => resource.bookmarked) : resources;
  const filtered = scopedResources.filter((resource) => `${resource.title} ${resource.subject} ${resource.chapter ?? ""}`.toLowerCase().includes(query.toLowerCase()) && (type === "All" || resource.resource_type === type) && (subject === "All" || resource.subject === subject) && (chapter === "All" || resource.chapter === chapter));
  const grouped = filtered.filter((resource) => resource.official_icai).reduce((groups, resource) => { const group = groups.get(resource.subject) ?? []; group.push(resource); groups.set(resource.subject, group); return groups; }, new Map<string, ResourceItem[]>());
  const officialGroups = Array.from(grouped.entries()).map(([groupSubject, modules]) => ({ subject: groupSubject, modules }));
  const selectedGroup = officialGroups.find((group) => group.subject === selectedSubject) ?? null;
  const regularResources = filtered.filter((resource) => !resource.official_icai);

  const toggleBookmark = async (resource: ResourceItem) => {
    try { await apiFetch(`/api/v1/resources/${resource.id}/bookmark`, { method: "POST" }); setResources((current) => current.map((item) => item.id === resource.id ? { ...item, bookmarked: !item.bookmarked } : item)); setNotice(resource.bookmarked ? "Removed from your library" : "Saved to your library"); } catch (error) { setNotice(error instanceof ApiError ? error.message : "Could not update your library"); }
  };
  const complete = async (resource: ResourceItem) => {
    try { await apiFetch(`/api/v1/resources/${resource.id}/progress`, { method: "PATCH", body: JSON.stringify({ completed: !resource.completed }) }); setResources((current) => current.map((item) => item.id === resource.id ? { ...item, completed: !item.completed } : item)); } catch { setNotice("Could not update progress"); }
  };

  return <><div className="feature-toolbar"><div className="feature-search"><Icon name="search" size={17} /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search title, subject or chapter" /></div><span className="section-kicker">Authorised material · live API catalogue</span></div><div className="filter-row"><span className="section-kicker">Your level</span><strong>{resources[0]?.level ?? "Your CA level"}</strong>{types.map((item) => <FilterChip active={type === item} key={item} onClick={() => setType(item)}>{item}</FilterChip>)}<select className="filter-chip" value={subject} onChange={(event) => { setSubject(event.target.value); setChapter("All"); setSelectedSubject(null); setOpenModule(null); }} aria-label="Filter by subject">{subjects.map((item) => <option key={item} value={item}>{item === "All" ? "All subjects" : item}</option>)}</select><select className="filter-chip" value={chapter} onChange={(event) => { setChapter(event.target.value); setSelectedSubject(null); setOpenModule(null); }} aria-label="Filter by chapter">{chapters.map((item) => <option key={item} value={item}>{item === "All" ? "All chapters" : item}</option>)}</select></div>{notice ? <div className="inline-notice"><Icon name="check" size={15} /> {notice}</div> : null}{loading ? <div className="resource-grid">{[1, 2, 3].map((item) => <div className="skeleton-card" key={item} />)}</div> : selectedGroup ? <><div className="material-detail-header"><button className="text-button" onClick={() => { setSelectedSubject(null); setOpenModule(null); }}><Icon name="arrow-left" size={14} /> All latest material</button><div><span className="section-kicker">Latest official ICAI material</span><h2>{selectedGroup.subject}</h2><p>Select a chapter or unit. The official PDF opens below without copying it into CA OS.</p></div></div><div className="resource-grid official-module-grid">{selectedGroup.modules.map((resource) => <article className="resource-card official-module-tile" key={resource.id}><div className="resource-card-top"><div className="resource-file-icon"><Icon name="file-text" size={20} /></div><button className={`icon-button ${resource.bookmarked ? "icon-button-active" : ""}`} onClick={() => toggleBookmark(resource)} aria-label={resource.bookmarked ? "Remove bookmark" : "Bookmark resource"}><Icon name="bookmark" size={16} /></button></div><div className="resource-card-body"><div className="resource-type-line"><span>{isDirectPdf(resource.source) ? "PDF module" : "Official page"}</span>{resource.completed ? <span className="official-badge">Completed</span> : null}</div><h3>{resource.chapter ?? resource.title}</h3><p>{resource.title}</p></div><div className="resource-card-footer"><span>{isDirectPdf(resource.source) ? "Open in app" : "Source page"}</span><div className="resource-card-actions"><button onClick={() => setOpenModule(resource)}><Icon name={isDirectPdf(resource.source) ? "file-text" : "arrow-up-right"} size={13} /> {isDirectPdf(resource.source) ? "View PDF" : "Open source"}</button><button className={resource.completed ? "completed-action" : ""} onClick={() => complete(resource)}>{resource.completed ? "Done" : "Complete"}</button></div></div></article>)}</div>{openModule ? <section className="official-pdf-viewer"><div className="official-pdf-viewer-header"><div><span className="section-kicker">In-app official viewer</span><h2>{openModule.chapter ?? openModule.title}</h2><p>Source: ICAI official link. CA OS does not download or mirror this material.</p></div><button className="icon-button" onClick={() => setOpenModule(null)} aria-label="Close material viewer"><Icon name="x" size={18} /></button></div>{isDirectPdf(openModule.source) ? <iframe title={openModule.title} src={`${API_BASE_URL}/api/v1/resources/${openModule.id}/download`} className="official-pdf-frame" /> : <div className="official-source-fallback"><p>This item is maintained on an ICAI source page. Open it to see the latest applicable chapter links.</p><a href={openModule.source ?? "https://www.icai.org/post/study-material-nset"} target="_blank" rel="noreferrer" className="button button-primary">Open ICAI source <Icon name="arrow-up-right" size={14} /></a></div>}</section> : null}</> : <>{officialGroups.length ? <><div className="material-section-heading"><div><span className="section-kicker">Latest official material</span><h2>Choose a subject to see chapter-wise PDFs.</h2></div><span>{officialGroups.reduce((count, group) => count + group.modules.length, 0)} chapter/module tiles</span></div><div className="resource-grid official-material-grid">{officialGroups.map((group) => <OfficialMaterialTile group={group} key={group.subject} onOpen={() => { setSelectedSubject(group.subject); setOpenModule(null); }} />)}</div></> : null}{regularResources.length ? <><div className="material-section-heading"><div><span className="section-kicker">Your library</span><h2>Uploaded and saved resources.</h2></div></div><div className="resource-grid">{regularResources.map((resource) => <ResourceTile key={resource.id} resource={resource} onBookmark={toggleBookmark} onComplete={complete} />)}</div></> : null}{!officialGroups.length && !regularResources.length ? <EmptyState icon="book-open" title={view === "library" ? "Your library is empty." : view === "past-papers" ? "No past papers are published yet." : "Your resource shelf is ready."} body={view === "library" ? "Bookmark a resource and it will appear here for your next study session." : view === "past-papers" ? "Published past papers will appear here with filters and progress tracking." : "Once authorised material is published, it will appear here with filters, bookmarks and progress tracking."} /> : null}</>}</>;
}

type McqItem = { id: string; prompt: string; options: string[]; subject: string; chapter?: string | null; difficulty: string };
type TestItem = { id: string; title: string; description?: string | null; duration_minutes: number; marks: number; question_count: number; question_ids?: string[]; status: string };
type SyllabusItem = { id: string; subject: string; chapter: string; total_topics: number; completed_topics: number; progress: number; status: string };
type PlanTask = { id: string; title: string; subject?: string | null; due_date: string; minutes: number; completed: boolean };
type RevisionItem = { id: string; title: string; subject?: string | null; due_at: string; status: string };
type QueryItem = { id: string; title: string; subject: string; body: string; answer?: string | null; status: string };

function McqWorkspace() {
  const [questions, setQuestions] = useState<McqItem[]>([]);
  const [index, setIndex] = useState(0);
  const [selected, setSelected] = useState<number | null>(null);
  const [result, setResult] = useState<{ correct: boolean; correct_option: number; explanation: string; score: number } | null>(null);
  const [loading, setLoading] = useState(true);
  useEffect(() => { apiFetch<McqItem[]>("/api/v1/mcqs").then(setQuestions).catch(() => setQuestions([])).finally(() => setLoading(false)); }, []);
  if (loading) return <div className="practice-layout"><section className="practice-card"><div className="skeleton-card" /></section></div>;
  if (!questions.length) return <EmptyState icon="circle-help" title="Your practice bank is ready." body="An administrator needs to publish MCQs before practice can begin." href="/admin/mcqs" action="Open MCQ manager" />;
  const question = questions[index % questions.length];
  const submit = async () => { if (selected === null) return; try { const answer = await apiFetch<typeof result>(`/api/v1/mcqs/${question.id}/answer`, { method: "POST", body: JSON.stringify({ selected_option: selected }) }); setResult(answer); } catch { setResult(null); } };
  const next = () => { setIndex((current) => (current + 1) % questions.length); setSelected(null); setResult(null); };
  return <div className="practice-layout"><section className="practice-card"><div className="practice-meta"><span>Question {(index % questions.length) + 1} of {questions.length}</span><span>{question.chapter ?? question.subject}</span></div><div className="practice-progress"><span style={{ width: `${(((index % questions.length) + 1) / questions.length) * 100}%` }} /></div><h2>{question.prompt}</h2><div className="option-list">{question.options.map((option, optionIndex) => <button key={option} className={`option-row ${selected === optionIndex ? "option-selected" : ""} ${result && optionIndex === result.correct_option ? "option-correct" : ""} ${result && selected === optionIndex && !result.correct ? "option-wrong" : ""}`} onClick={() => !result && setSelected(optionIndex)}><span>{String.fromCharCode(65 + optionIndex)}</span>{option}{result && optionIndex === result.correct_option ? <Icon name="check" size={16} /> : null}</button>)}</div>{result ? <div className={`answer-explanation ${result.correct ? "answer-success" : "answer-error"}`}><strong>{result.correct ? "Correct. Keep that concept." : "Review this one before moving on."}</strong><p>{result.explanation}</p><small>Session accuracy: {result.score}%</small></div> : null}<div className="practice-actions">{result ? <button className="button button-primary" onClick={next}>Next question <Icon name="arrow-right" size={15} /></button> : <button className="button button-primary" onClick={submit} disabled={selected === null}>Submit answer</button>}<Link href="/mcq/mistakes" className="text-button">My mistakes <Icon name="arrow-right" size={14} /></Link></div></section><aside className="practice-side"><div className="mini-score"><span className="section-kicker">Live practice</span><strong>{result?.score ?? 0}%</strong><p>Your score is saved to the wrong-answer and analytics APIs.</p></div><div className="side-list"><span className="section-kicker">Practice modes</span><Link href="/mcq">Chapter wise <Icon name="arrow-right" size={14} /></Link><Link href="/mcq/mistakes">Wrong answers <Icon name="arrow-right" size={14} /></Link></div></aside></div>;
}

function TestsWorkspace() {
  const [tests, setTests] = useState<TestItem[]>([]);
  const [activeTest, setActiveTest] = useState<TestItem | null>(null);
  const [questions, setQuestions] = useState<McqItem[]>([]);
  const [answers, setAnswers] = useState<Record<string, number>>({});
  const [result, setResult] = useState<{ score: number; correct_answers: number; total_questions: number } | null>(null);
  const [status, setStatus] = useState<string | null>(null);
  useEffect(() => { apiFetch<TestItem[]>("/api/v1/tests").then(setTests).catch(() => setTests([])); }, []);
  const start = async (test: TestItem) => {
    setStatus(null); setResult(null); setAnswers({});
    try {
      const bank = await apiFetch<McqItem[]>("/api/v1/mcqs");
      setQuestions(bank.filter((question) => test.question_ids?.includes(question.id)));
      setActiveTest(test);
    } catch (error) { setStatus(error instanceof ApiError ? error.message : "Could not open this test."); }
  };
  const submit = async (event: React.FormEvent) => {
    event.preventDefault();
    if (!activeTest) return;
    try { const response = await apiFetch<typeof result>(`/api/v1/tests/${activeTest.id}/submit`, { method: "POST", body: JSON.stringify({ answers }) }); setResult(response); } catch (error) { setStatus(error instanceof ApiError ? error.message : "Could not submit this test."); }
  };
  if (activeTest) return <div className="dashboard-card practice-card"><div className="practice-meta"><span>{activeTest.title}</span><span>{activeTest.duration_minutes} min · {activeTest.marks} marks</span></div><h2>Complete the assessment.</h2>{questions.length ? <form onSubmit={submit}><div className="option-list">{questions.map((question, index) => <fieldset className="test-question" key={question.id}><legend>{index + 1}. {question.prompt}</legend>{question.options.map((option, optionIndex) => <label className="checkbox-row" key={option}><input type="radio" name={question.id} checked={answers[question.id] === optionIndex} onChange={() => setAnswers((current) => ({ ...current, [question.id]: optionIndex }))} />{option}</label>)}</fieldset>)}</div>{result ? <div className="answer-explanation answer-success"><strong>Test submitted: {result.score} marks</strong><p>{result.correct_answers} of {result.total_questions} answers were correct.</p></div> : <button className="button button-primary" type="submit">Submit test <Icon name="check" size={15} /></button>}{status ? <div className="form-error">{status}</div> : null}</form> : <EmptyState icon="clipboard-check" title="The questions are unavailable." body="Ask an administrator to republish this test with active MCQs." />}</div>;
  if (!tests.length) return <EmptyState icon="clipboard-check" title="Your test series is ready." body="An administrator needs to publish a test before it appears here." href="/admin/tests" action="Open test manager" />;
  return <div className="test-list">{tests.map((test) => <article className="test-card" key={test.id}><div className="test-card-icon"><Icon name="clipboard-check" size={20} /></div><div className="test-card-copy"><span className="section-kicker">{test.status}</span><h3>{test.title}</h3><p><span><Icon name="clock-3" size={13} /> {test.duration_minutes} min</span><span><Icon name="file-text" size={13} /> {test.marks} marks · {test.question_count} questions</span></p></div><div className="test-card-action"><button className="button button-soft" onClick={() => start(test)} disabled={test.status !== "open"}>{test.status !== "open" ? "Unavailable" : "Start test"}<Icon name="arrow-right" size={14} /></button></div></article>)}</div>;
}

function SyllabusWorkspace() {
  const [items, setItems] = useState<SyllabusItem[]>([]);
  useEffect(() => { apiFetch<SyllabusItem[]>("/api/v1/syllabus").then(setItems).catch(() => setItems([])); }, []);
  const update = async (item: SyllabusItem) => { const next = await apiFetch<SyllabusItem>(`/api/v1/syllabus/${item.id}`, { method: "PATCH", body: JSON.stringify({ completed_topics: Math.min(item.total_topics, item.completed_topics + 1), status: "in_progress" }) }); setItems((current) => current.map((candidate) => candidate.id === item.id ? next : candidate)); };
  const overall = items.length ? Math.round(items.reduce((sum, item) => sum + item.progress, 0) / items.length) : 0;
  return <div className="syllabus-layout"><section className="dashboard-card syllabus-overview"><div className="radial-progress"><span><strong>{overall}%</strong><small>overall</small></span></div><div><span className="section-kicker">Current attempt</span><h2>{items.filter((item) => item.progress > 0).length} of {items.length} chapters in motion.</h2><p>Progress is persisted to your syllabus tracker.</p></div></section><div className="subject-progress-grid">{items.map((item, index) => <article className="subject-progress-card" key={item.id}><div className={`subject-badge subject-${["violet", "coral", "blue", "mint"][index % 4]}`}>{item.subject.split(" ").map((word) => word[0]).join("").slice(0, 3)}</div><div className="subject-progress-copy"><div><h3>{item.subject}</h3><strong>{Math.round(item.progress)}%</strong></div><div className="progress-track"><span className={`progress-fill fill-${["violet", "coral", "blue", "mint"][index % 4]}`} style={{ width: `${item.progress}%` }} /></div><p>{item.chapter} · {item.completed_topics} of {item.total_topics} topics</p></div><button className="icon-button" onClick={() => update(item)} aria-label={`Update ${item.chapter}`}><Icon name="plus" size={16} /></button></article>)}</div></div>;
}

function PlannerWorkspace() {
  const [tasks, setTasks] = useState<PlanTask[]>([]); const [draft, setDraft] = useState("");
  useEffect(() => { apiFetch<PlanTask[]>("/api/v1/planner").then(setTasks).catch(() => setTasks([])); }, []);
  const toggle = async (task: PlanTask) => { const updated = await apiFetch<PlanTask>(`/api/v1/planner/${task.id}`, { method: "PATCH", body: JSON.stringify({ completed: !task.completed }) }); setTasks((current) => current.map((item) => item.id === task.id ? updated : item)); };
  const add = async (event: React.FormEvent) => { event.preventDefault(); if (!draft.trim()) return; const task = await apiFetch<PlanTask>("/api/v1/planner", { method: "POST", body: JSON.stringify({ title: draft.trim(), subject: "Custom task", due_date: new Date().toISOString().slice(0, 10), minutes: 30 }) }); setTasks((current) => [...current, task]); setDraft(""); };
  return <div className="planner-layout"><section className="dashboard-card planner-day"><div className="card-heading"><div><span className="section-kicker">Your study plan</span><h2>Plan for today</h2></div><span className="streak-pill"><Icon name="flame" size={14} /> {tasks.filter((task) => task.completed).length} complete</span></div>{tasks.length ? tasks.map((task) => <button className={`planner-task ${task.completed ? "planner-task-done" : ""}`} key={task.id} onClick={() => toggle(task)}><span className="task-check">{task.completed ? <Icon name="check" size={13} /> : null}</span><span className="task-copy"><strong>{task.title}</strong><small>{task.subject ?? "Study"} · {task.due_date}</small></span><span className="task-duration">{task.minutes} min</span><Icon name="arrow-right" size={15} /></button>) : <EmptyState icon="calendar-days" title="No tasks yet." body="Add your first study task below." />}{<form className="inline-add" onSubmit={add}><input value={draft} onChange={(event) => setDraft(event.target.value)} placeholder="Add a custom task" /><button className="icon-button" aria-label="Add task"><Icon name="plus" size={16} /></button></form>}</section><aside className="dashboard-card plan-sidebar"><span className="section-kicker">Plan health</span><strong>{tasks.length ? Math.round((tasks.filter((task) => task.completed).length / tasks.length) * 100) : 0}%</strong><p>of your persisted study tasks are complete.</p><Link href="/revision" className="outline-button">Build a revision plan <Icon name="arrow-up-right" size={14} /></Link></aside></div>;
}

function RevisionWorkspace() {
  const [items, setItems] = useState<RevisionItem[]>([]);
  useEffect(() => { apiFetch<RevisionItem[]>("/api/v1/revision").then(setItems).catch(() => setItems([])); }, []);
  const complete = async (item: RevisionItem) => { const updated = await apiFetch<RevisionItem>(`/api/v1/revision/${item.id}`, { method: "PATCH", body: JSON.stringify({ status: "completed" }) }); setItems((current) => current.filter((candidate) => candidate.id !== updated.id)); };
  return <div className="revision-layout"><div className="revision-timeline">{items.length ? items.map((item) => <article className={`revision-item revision-${item.status}`} key={item.id}><div className="revision-date"><strong>{new Date(item.due_at).getDate()}</strong><span>{new Date(item.due_at).toLocaleString("en-IN", { month: "short" }).toUpperCase()}</span></div><div className="revision-line" /><div className="revision-copy"><span className="section-kicker">{item.status}</span><h3>{item.title}</h3><p>{item.subject ?? "General"}</p></div><button className="button button-soft" onClick={() => complete(item)}>Complete</button></article>) : <EmptyState icon="rotate-ccw" title="Your revision queue is clear." body="Revision items generated from study activity will appear here." href="/planner" action="Open study planner" />}</div><aside className="dashboard-card revision-aside"><div className="section-kicker">Revision rhythm</div><h2>Return before recall fades.</h2><p>Completed revision items are removed from the active queue and remain in analytics.</p><Link href="/planner" className="button button-primary">Open study planner <Icon name="arrow-right" size={14} /></Link></aside></div>;
}

type VideoItem = { id: string; title: string; description?: string | null; level: string; subject: string; chapter?: string | null; video_url: string; duration_minutes: number };
type OpportunityItem = { id: string; kind: string; title: string; organisation?: string | null; location?: string | null; description: string; application_url?: string | null; target_level?: string | null };
type OfficialUpdateItem = { id: string; title: string; body: string; category: string; source_url: string; published_at: string };

function VideosWorkspace() {
  const [videos, setVideos] = useState<VideoItem[]>([]);
  useEffect(() => { apiFetch<VideoItem[]>("/api/v1/videos").then(setVideos).catch(() => setVideos([])); }, []);
  if (!videos.length) return <EmptyState icon="play-square" title="Your video library is ready." body="Published lessons for your CA level will appear here." />;
  return <div className="video-grid">{videos.map((video) => <article className="video-card" key={video.id}><button className="video-thumbnail" onClick={() => window.open(video.video_url, "_blank", "noopener,noreferrer")}><span className="play-button"><Icon name="play-square" size={20} /></span><span className="video-duration">{video.duration_minutes} min</span></button><div className="video-card-copy"><span className="section-kicker">{video.subject}{video.chapter ? ` · ${video.chapter}` : ""}</span><h3>{video.title}</h3><p>{video.description ?? `${video.level} lesson`}</p><button className="text-button" onClick={() => window.open(video.video_url, "_blank", "noopener,noreferrer")}>Watch lesson <Icon name="arrow-right" size={14} /></button></div></article>)}</div>;
}

function OpportunityWorkspace({ kind }: { kind: "career" | "articleship" }) {
  const [items, setItems] = useState<OpportunityItem[]>([]);
  useEffect(() => { apiFetch<OpportunityItem[]>(`/api/v1/opportunities?kind=${kind}`).then(setItems).catch(() => setItems([])); }, [kind]);
  if (!items.length) return <EmptyState icon={kind === "career" ? "compass" : "briefcase-business"} title="No opportunities published yet." body="The admin team will publish verified opportunities here." />;
  return <div className="generic-list">{items.map((item) => <article className="generic-row" key={item.id}><div className="generic-row-icon"><Icon name={kind === "career" ? "compass" : "briefcase-business"} size={17} /></div><div><strong>{item.title}</strong><small>{item.organisation ?? "Opportunity"} · {item.location ?? "Flexible"} · {item.description}</small></div>{item.application_url ? <a href={item.application_url} target="_blank" rel="noreferrer" className="text-button">Apply <Icon name="arrow-up-right" size={14} /></a> : null}</article>)}</div>;
}

function OfficialUpdatesWorkspace() {
  const [items, setItems] = useState<OfficialUpdateItem[]>([]);
  useEffect(() => { apiFetch<OfficialUpdateItem[]>("/api/v1/official-updates").then(setItems).catch(() => setItems([])); }, []);
  if (!items.length) return <EmptyState icon="landmark" title="No official updates yet." body="Only updates with a source URL will be published in this feed." />;
  return <div className="generic-list">{items.map((item) => <article className="generic-row" key={item.id}><div className="generic-row-icon"><Icon name="landmark" size={17} /></div><div><strong>{item.title}</strong><small>{item.category} · {item.body}</small></div><a href={item.source_url} target="_blank" rel="noreferrer" className="text-button">Official source <Icon name="arrow-up-right" size={14} /></a></article>)}</div>;
}

function QueriesWorkspace() {
  const [body, setBody] = useState(""); const [queries, setQueries] = useState<QueryItem[]>([]); const [submitting, setSubmitting] = useState(false);
  useEffect(() => { apiFetch<QueryItem[]>("/api/v1/queries").then(setQueries).catch(() => setQueries([])); }, []);
  const submit = async (event: React.FormEvent) => { event.preventDefault(); if (!body.trim()) return; setSubmitting(true); try { const item = await apiFetch<QueryItem>("/api/v1/queries", { method: "POST", body: JSON.stringify({ subject: "General", title: body.trim().slice(0, 80), body: body.trim() }) }); setQueries((current) => [item, ...current]); setBody(""); } finally { setSubmitting(false); } };
  return <div className="query-layout"><section className="dashboard-card query-form-card"><div className="section-kicker">New query</div><h2>Ask with context.</h2><p>Your question is saved and can be answered by an assigned faculty member.</p><form onSubmit={submit}><input value={body} onChange={(event) => setBody(event.target.value)} placeholder="What are you unsure about?" required /><button className="button button-primary" disabled={submitting}>{submitting ? "Saving…" : "Submit query"} <Icon name="arrow-right" size={14} /></button></form></section><section className="dashboard-card query-list"><div className="card-heading"><div><span className="section-kicker">Your queue</span><h2>Queries and replies</h2></div></div>{queries.length ? queries.map((item) => <div className="query-row" key={item.id}><span className={`query-status query-status-${item.status.toLowerCase()}`} /> <div><strong>{item.title}</strong><small>{item.subject}{item.answer ? ` · ${item.answer}` : ""}</small></div><span>{item.status}</span><Icon name="arrow-right" size={15} /></div>) : <EmptyState icon="message-circle" title="No queries yet." body="Ask your first faculty question from the form." />}</section></div>;
}

function AIWorkspace() {
  const [prompt, setPrompt] = useState(""); const [answer, setAnswer] = useState<string | null>(null); const [status, setStatus] = useState<string | null>(null); const [loading, setLoading] = useState(false);
  const submit = async (event: React.FormEvent) => { event.preventDefault(); setStatus(null); setAnswer(null); setLoading(true); try { const result = await apiFetch<{ answer: string; disclaimer: string }>("/api/v1/ai/assist", { method: "POST", body: JSON.stringify({ prompt }) }); setAnswer(`${result.answer}\n\n${result.disclaimer}`); } catch (error) { setStatus(error instanceof ApiError ? error.message : "AI assistant is unavailable."); } finally { setLoading(false); } };
  return <div className="generic-workspace"><div className="dashboard-card generic-intro"><div className="generic-intro-icon"><Icon name="sparkles" size={23} /></div><div><span className="section-kicker">AI responses are labelled</span><h2>Ask a focused study question.</h2><p>Use AI for explanations and revision structure. Verify provisions, dates and official rules against primary sources.</p></div></div><form className="dashboard-card query-form-card" onSubmit={submit}><textarea value={prompt} onChange={(event) => setPrompt(event.target.value)} placeholder="Explain a concept, compare two topics or create a revision checklist…" required minLength={3} /><button className="button button-primary" disabled={loading}>{loading ? "Thinking…" : "Ask assistant"}<Icon name="arrow-right" size={14} /></button></form>{status ? <div className="form-error"><Icon name="circle-help" size={15} /> {status}</div> : null}{answer ? <article className="dashboard-card generic-intro"><div className="generic-intro-icon"><Icon name="sparkles" size={23} /></div><div><span className="section-kicker">Assistant response</span><p style={{ whiteSpace: "pre-wrap" }}>{answer}</p></div></article> : null}</div>;
}

type NotificationItem = { id: string; title: string; body: string; kind: string; read_at?: string | null; created_at: string };
type AnalyticsItem = { mcq_attempts: number; mcq_accuracy: number; completed_resources: number; completed_tasks: number; pending_revision: number; test_attempts: number; open_queries: number };
type AccountItem = { email: string; full_name: string; status: string; roles: string[]; student_level?: string | null; student_group?: string | null; student_attempt?: string | null };

function NotificationsWorkspace() {
  const [items, setItems] = useState<NotificationItem[]>([]);
  useEffect(() => { apiFetch<NotificationItem[]>("/api/v1/notifications").then(setItems).catch(() => setItems([])); }, []);
  const markRead = async (item: NotificationItem) => { try { await apiFetch(`/api/v1/notifications/${item.id}/read`, { method: "PATCH" }); setItems((current) => current.map((candidate) => candidate.id === item.id ? { ...candidate, read_at: new Date().toISOString() } : candidate)); } catch { /* keep the notification visible if the update fails */ } };
  return <div className="dashboard-card generic-list"><div className="section-kicker">Your feed</div><h2>Notifications</h2>{items.length ? items.map((item) => <article className={`generic-row ${item.read_at ? "notification-read" : ""}`} key={item.id}><div className="generic-row-icon"><Icon name={item.kind === "evaluation" ? "file-check-2" : "bell"} size={17} /></div><div><strong>{item.title}</strong><small>{item.body} · {new Date(item.created_at).toLocaleString("en-IN")}</small></div>{item.read_at ? <span>Read</span> : <button className="button button-soft" onClick={() => markRead(item)}>Mark read</button>}</article>) : <EmptyState icon="bell" title="You are all caught up." body="Evaluation updates, faculty replies and study reminders will appear here." />}</div>;
}

function AnalyticsWorkspace() {
  const [summary, setSummary] = useState<AnalyticsItem | null>(null);
  useEffect(() => { apiFetch<AnalyticsItem>("/api/v1/analytics/summary").then(setSummary).catch(() => setSummary(null)); }, []);
  const metrics = summary ? [["MCQ accuracy", `${summary.mcq_accuracy}%`, `${summary.mcq_attempts} attempts`], ["Resources completed", String(summary.completed_resources), "Persisted library progress"], ["Tasks completed", String(summary.completed_tasks), "Study planner activity"], ["Revision due", String(summary.pending_revision), "Return before it fades"], ["Tests attempted", String(summary.test_attempts), "Assessment history"], ["Open queries", String(summary.open_queries), "Support queue"]] : [];
  return <div className="admin-metric-grid">{metrics.length ? metrics.map(([label, value, detail]) => <article className="metric-card metric-blue" key={label}><div className="metric-top"><span>{label}</span><Icon name="chart-no-axes-combined" size={14} /></div><div className="metric-value-row"><strong>{value}</strong></div><div className="metric-bottom"><span>{detail}</span></div></article>) : <EmptyState icon="chart-no-axes-combined" title="Analytics will appear after activity." body="Answer an MCQ, complete a resource or add a study task to start building your preparation view." />}</div>;
}

function AccountWorkspace({ settings = false }: { settings?: boolean }) {
  const [account, setAccount] = useState<AccountItem | null>(null);
  useEffect(() => { apiFetch<AccountItem>("/api/v1/auth/me").then(setAccount).catch(() => setAccount(null)); }, []);
  if (!account) return <EmptyState icon={settings ? "settings" : "user-round"} title="Account details are unavailable." body="Sign in again after starting the API to load your protected account details." />;
  return <div className="dashboard-card generic-list"><div className="section-kicker">{settings ? "Workspace settings" : "Profile"}</div><h2>{account.full_name}</h2><div className="generic-row"><div className="generic-row-icon"><Icon name="mail" size={17} /></div><div><strong>Email address</strong><small>{account.email}</small></div><span>{account.status}</span></div><div className="generic-row"><div className="generic-row-icon"><Icon name="shield-check" size={17} /></div><div><strong>Access roles</strong><small>{account.roles.join(", ")}</small></div></div>{account.student_level ? <div className="generic-row"><div className="generic-row-icon"><Icon name="graduation-cap" size={17} /></div><div><strong>Current attempt</strong><small>{account.student_level} · {account.student_group ?? "Group not set"} · {account.student_attempt ?? "Attempt not set"}</small></div></div> : null}<div className="inline-notice"><Icon name="check" size={15} /> Sessions are protected with rotating HttpOnly refresh tokens.</div></div>;
}

function TimetableWorkspace() {
  const [tasks, setTasks] = useState<PlanTask[]>([]);
  useEffect(() => { apiFetch<PlanTask[]>("/api/v1/planner").then(setTasks).catch(() => setTasks([])); }, []);
  const grouped = tasks.reduce((groups, task) => { const current = groups.get(task.due_date) ?? []; current.push(task); groups.set(task.due_date, current); return groups; }, new Map<string, PlanTask[]>());
  return <div className="dashboard-card generic-list"><div className="section-kicker">Persisted study calendar</div><h2>Your timetable</h2>{grouped.size ? Array.from(grouped.entries()).map(([date, entries]) => <section key={date} className="generic-row"><div className="generic-row-icon"><Icon name="calendar-check" size={17} /></div><div><strong>{new Date(`${date}T00:00:00`).toLocaleDateString("en-IN", { weekday: "long", day: "numeric", month: "short" })}</strong><small>{entries.map((task) => `${task.title} · ${task.minutes} min`).join(" | ")}</small></div><span>{entries.length} block{entries.length === 1 ? "" : "s"}</span></section>) : <EmptyState icon="calendar-days" title="Your timetable is empty." body="Add study blocks from the Study Planner and they will appear here." href="/planner" action="Open planner" />}</div>;
}

function FacultyStudentsWorkspace() {
  const [papers, setPapers] = useState<PaperItem[]>([]);
  useEffect(() => { apiFetch<PaperItem[]>("/api/v1/papers").then(setPapers).catch(() => setPapers([])); }, []);
  return <div className="dashboard-card generic-list"><div className="section-kicker">Assigned scope</div><h2>Students represented in your queue</h2>{papers.length ? papers.map((paper) => <article className="generic-row" key={paper.id}><div className="generic-row-icon"><Icon name="user-round" size={17} /></div><div><strong>{paper.title}</strong><small>{paper.subject} · Submitted {new Date(paper.created_at).toLocaleDateString("en-IN")} · {paper.status}</small></div><Link className="button button-soft" href="/faculty/papers">Open paper queue</Link></article>) : <EmptyState icon="user-round" title="No students assigned yet." body="Only papers assigned to your faculty scope are shown here." />}</div>;
}

function GenericWorkspace({ routeKey }: { routeKey: string }) {
  const copy = pageCopy[routeKey] ?? { eyebrow: "Workspace", title: "A focused space for your next step.", body: "This workspace is connected to the CA OS navigation and is ready for the next domain integration.", icon: "sparkles" };
  const [filter, setFilter] = useState(""); const [saved, setSaved] = useState<string[]>([]);
  const items = routeKey === "icai-updates" ? ["Exam form deadlines and official notices", "BOS learning resources", "Amendments for the current attempt"] : routeKey === "career" ? ["Audit and assurance roadmap", "Tax technology skill path", "Financial reporting opportunities"] : routeKey === "articleship" ? ["Audit articleship · Ahmedabad", "Industrial training · Financial reporting", "Risk advisory · Mumbai"] : ["Your saved study moments", "Recommended for your attempt", "Continue where you left off"];
  return <div className="generic-workspace"><div className="dashboard-card generic-intro"><div className="generic-intro-icon"><Icon name={copy.icon} size={23} /></div><div><span className="section-kicker">{routeKey === "ai" ? "AI-generated responses are always labelled" : "Connected workspace"}</span><h2>{routeKey === "ai" ? "Ask a focused question." : "A clear next step is better than a crowded page."}</h2><p>{routeKey === "ai" ? "Explain a concept, compare two ideas or turn a chapter into a revision checklist. Verify official rules against primary sources." : copy.body}</p></div></div><div className="feature-toolbar"><div className="feature-search"><Icon name="search" size={17} /><input value={filter} onChange={(event) => setFilter(event.target.value)} placeholder={`Search ${routeKey.replaceAll("-", " ")}`} /></div><button className="button button-primary" onClick={() => setSaved((current) => [...current, `New ${routeKey} item`])}><Icon name="plus" size={15} /> Add to workspace</button></div><div className="generic-list">{items.filter((item) => item.toLowerCase().includes(filter.toLowerCase())).map((item) => <article className="generic-row" key={item}><div className="generic-row-icon"><Icon name={copy.icon} size={17} /></div><div><strong>{item}</strong><small>{routeKey === "icai-updates" ? "Original source link available" : "Structured for your current attempt"}</small></div><button className={`icon-button ${saved.includes(item) ? "icon-button-active" : ""}`} onClick={() => setSaved((current) => current.includes(item) ? current.filter((entry) => entry !== item) : [...current, item])} aria-label="Save"><Icon name="bookmark" size={16} /></button><Icon name="arrow-right" size={15} /></article>)}</div>{saved.length ? <div className="inline-notice"><Icon name="check" size={15} /> {saved.length} item{saved.length > 1 ? "s" : ""} saved to your workspace.</div> : null}</div>;
}

function AdminMcqManager() {
  const [questions, setQuestions] = useState<McqItem[]>([]); const [status, setStatus] = useState<string | null>(null);
  const [form, setForm] = useState({ prompt: "", subject: "Advanced Accounting", chapter: "", explanation: "", difficulty: "medium", correct_option: "0", options: ["", "", "", ""] });
  useEffect(() => { apiFetch<McqItem[]>("/api/v1/mcqs").then(setQuestions).catch(() => setQuestions([])); }, []);
  const submit = async (event: React.FormEvent) => { event.preventDefault(); setStatus(null); try { const created = await apiFetch<McqItem>("/api/v1/mcqs", { method: "POST", body: JSON.stringify({ ...form, options: form.options, correct_option: Number(form.correct_option) }) }); setQuestions((current) => [created, ...current]); setStatus("MCQ published successfully."); setForm((current) => ({ ...current, prompt: "", explanation: "", options: ["", "", "", ""] })); } catch (error) { setStatus(error instanceof ApiError ? error.message : "Could not publish MCQ."); } };
  return <div className="admin-manager-layout"><section className="dashboard-card upload-card"><div className="section-kicker">Practice content</div><h2>Publish a real MCQ.</h2><form className="admin-upload-form" onSubmit={submit}><label>Question<input value={form.prompt} onChange={(event) => setForm({ ...form, prompt: event.target.value })} required /></label>{form.options.map((option, index) => <label key={index}>Option {String.fromCharCode(65 + index)}<input value={option} onChange={(event) => setForm({ ...form, options: form.options.map((item, itemIndex) => itemIndex === index ? event.target.value : item) })} required /></label>)}<div className="admin-two-col"><label>Subject<input value={form.subject} onChange={(event) => setForm({ ...form, subject: event.target.value })} required /></label><label>Correct option<select value={form.correct_option} onChange={(event) => setForm({ ...form, correct_option: event.target.value })}><option value="0">A</option><option value="1">B</option><option value="2">C</option><option value="3">D</option></select></label></div><label>Explanation<textarea value={form.explanation} onChange={(event) => setForm({ ...form, explanation: event.target.value })} required /></label>{status ? <div className="inline-notice"><Icon name="check" size={15} /> {status}</div> : null}<button className="button button-primary">Publish MCQ <Icon name="arrow-up-right" size={14} /></button></form></section><section className="dashboard-card generic-list"><div className="section-kicker">Published bank</div><h2>{questions.length} MCQ{questions.length === 1 ? "" : "s"}</h2>{questions.map((question) => <div className="generic-row" key={question.id}><div className="generic-row-icon"><Icon name="circle-help" size={17} /></div><div><strong>{question.prompt}</strong><small>{question.subject} · {question.chapter ?? "General"}</small></div></div>)}</section></div>;
}

function AdminTestManager() {
  const [questions, setQuestions] = useState<McqItem[]>([]); const [tests, setTests] = useState<TestItem[]>([]); const [status, setStatus] = useState<string | null>(null); const [title, setTitle] = useState(""); const [selected, setSelected] = useState<string[]>([]);
  useEffect(() => { apiFetch<McqItem[]>("/api/v1/mcqs").then(setQuestions).catch(() => setQuestions([])); apiFetch<TestItem[]>("/api/v1/tests").then(setTests).catch(() => setTests([])); }, []);
  const submit = async (event: React.FormEvent) => { event.preventDefault(); try { const created = await apiFetch<TestItem>("/api/v1/tests", { method: "POST", body: JSON.stringify({ title, duration_minutes: 60, marks: selected.length, question_ids: selected }) }); setTests((current) => [created, ...current]); setTitle(""); setSelected([]); setStatus("Test published successfully."); } catch (error) { setStatus(error instanceof ApiError ? error.message : "Could not publish test."); } };
  return <div className="admin-manager-layout"><section className="dashboard-card upload-card"><div className="section-kicker">Assessment content</div><h2>Create a test.</h2><form className="admin-upload-form" onSubmit={submit}><label>Test title<input value={title} onChange={(event) => setTitle(event.target.value)} placeholder="e.g. Consolidation chapter test" required /></label><div className="section-kicker">Select MCQs</div>{questions.length ? questions.map((question) => <label className="checkbox-row" key={question.id}><input type="checkbox" checked={selected.includes(question.id)} onChange={(event) => setSelected((current) => event.target.checked ? [...current, question.id] : current.filter((id) => id !== question.id))} />{question.prompt}</label>) : <p>Publish MCQs first.</p>}{status ? <div className="inline-notice"><Icon name="check" size={15} /> {status}</div> : null}<button className="button button-primary" disabled={!selected.length}>Publish test <Icon name="arrow-up-right" size={14} /></button></form></section><section className="dashboard-card generic-list"><div className="section-kicker">Test series</div><h2>{tests.length} test{tests.length === 1 ? "" : "s"}</h2>{tests.map((test) => <div className="generic-row" key={test.id}><div className="generic-row-icon"><Icon name="clipboard-check" size={17} /></div><div><strong>{test.title}</strong><small>{test.question_count} questions · {test.marks} marks</small></div></div>)}</section></div>;
}

function AdminContentManager() {
  const [kind, setKind] = useState("video"); const [title, setTitle] = useState(""); const [level, setLevel] = useState("CA Intermediate"); const [subject, setSubject] = useState("Advanced Accounting"); const [chapter, setChapter] = useState(""); const [body, setBody] = useState(""); const [url, setUrl] = useState(""); const [organisation, setOrganisation] = useState(""); const [location, setLocation] = useState(""); const [status, setStatus] = useState<string | null>(null);
  const submit = async (event: React.FormEvent) => { event.preventDefault(); setStatus(null); try { if (kind === "video") await apiFetch("/api/v1/videos", { method: "POST", body: JSON.stringify({ title, level, subject, chapter: chapter || null, video_url: url, duration_minutes: 30, description: body || null }) }); else if (kind === "update") await apiFetch("/api/v1/official-updates", { method: "POST", body: JSON.stringify({ title, body, category: subject, source_url: url }) }); else await apiFetch("/api/v1/opportunities", { method: "POST", body: JSON.stringify({ kind, title, organisation, location, description: body, application_url: url || null, target_level: level }) }); setStatus("Content published successfully."); setTitle(""); setBody(""); setUrl(""); } catch (error) { setStatus(error instanceof ApiError ? error.message : "Could not publish content."); } };
  const syncIcaI = async () => { try { const result = await apiFetch<{ created: number; updated: number; total: number }>("/api/v1/resources/sync-icai", { method: "POST" }); setStatus(`ICAI catalog synced: ${result.created} new, ${result.updated} updated, ${result.total} official tiles.`); } catch (error) { setStatus(error instanceof ApiError ? error.message : "Could not sync ICAI material."); } };
  return <div className="admin-manager-layout"><section className="dashboard-card upload-card"><div className="section-kicker">Content operations</div><h2>Publish verified workspace content.</h2><p>Official ICAI cards store metadata and link to ICAI; they do not mirror copyrighted PDFs.</p><button type="button" className="button button-soft" onClick={syncIcaI}><Icon name="refresh-cw" size={14} /> Sync official ICAI study material</button><form className="admin-upload-form" onSubmit={submit}><label>Content type<select value={kind} onChange={(event) => setKind(event.target.value)}><option value="video">Video lesson</option><option value="career">Career opportunity</option><option value="articleship">Articleship opportunity</option><option value="update">Official ICAI update</option></select></label><label>Title<input value={title} onChange={(event) => setTitle(event.target.value)} required /></label>{kind !== "update" ? <div className="admin-two-col"><label>Level<select value={level} onChange={(event) => setLevel(event.target.value)}><option>CA Foundation</option><option>CA Intermediate</option><option>CA Final</option></select></label><label>{kind === "video" ? "Subject" : "Organisation"}<input value={kind === "video" ? subject : organisation} onChange={(event) => kind === "video" ? setSubject(event.target.value) : setOrganisation(event.target.value)} required /></label></div> : <label>Category<input value={subject} onChange={(event) => setSubject(event.target.value)} placeholder="Exam, BOS, Circular" required /></label>}{kind === "video" ? <label>Chapter<input value={chapter} onChange={(event) => setChapter(event.target.value)} /></label> : null}{kind !== "video" && kind !== "update" ? <label>Location<input value={location} onChange={(event) => setLocation(event.target.value)} /></label> : null}<label>{kind === "video" ? "Lesson description" : "Description / update body"}<textarea value={body} onChange={(event) => setBody(event.target.value)} required /></label><label>{kind === "update" ? "Official source URL" : kind === "video" ? "Video URL" : "Application URL"}<input type="url" value={url} onChange={(event) => setUrl(event.target.value)} required={kind !== "career" && kind !== "articleship"} /></label>{status ? <div className="inline-notice"><Icon name="check" size={15} /> {status}</div> : null}<button className="button button-primary">Publish <Icon name="arrow-up-right" size={14} /></button></form></section></div>;
}

type AdminUserItem = { id: string; email: string; full_name: string; status: string; roles: string[]; created_at: string };
type AuditItem = { id: string; actor_id?: string | null; action: string; resource_type: string; resource_id?: string | null; after_state?: Record<string, unknown> | null; created_at: string };

function AdminUsersWorkspace({ role }: { role: "student" | "faculty" }) {
  const [users, setUsers] = useState<AdminUserItem[]>([]);
  useEffect(() => { apiFetch<AdminUserItem[]>(`/api/v1/admin/users?role=${role}`).then(setUsers).catch(() => setUsers([])); }, [role]);
  return <div className="dashboard-card generic-list"><div className="section-kicker">Access management</div><h2>{role === "student" ? "Students" : "Faculty"}</h2>{users.length ? users.map((user) => <div className="generic-row" key={user.id}><div className="generic-row-icon"><Icon name={role === "student" ? "user-round" : "briefcase-business"} size={17} /></div><div><strong>{user.full_name}</strong><small>{user.email} · {user.status} · Joined {new Date(user.created_at).toLocaleDateString("en-IN")}</small></div><span className="upcoming-tag tag-ready">{user.roles.join(", ")}</span></div>) : <EmptyState icon="user-round" title={`No ${role} accounts yet.`} body="Accounts created through the secure registration/provisioning flow will appear here." />}</div>;
}

function AuditLogsWorkspace() {
  const [items, setItems] = useState<AuditItem[]>([]);
  useEffect(() => { apiFetch<AuditItem[]>("/api/v1/admin/audit-logs").then(setItems).catch(() => setItems([])); }, []);
  return <div className="dashboard-card generic-list"><div className="section-kicker">Security history</div><h2>Audit log</h2>{items.length ? items.map((item) => <div className="generic-row" key={item.id}><div className="generic-row-icon"><Icon name="shield-check" size={17} /></div><div><strong>{item.action}</strong><small>{item.resource_type} · {item.resource_id ?? "—"} · {new Date(item.created_at).toLocaleString("en-IN")}</small></div></div>) : <EmptyState icon="shield-check" title="No audit events yet." body="Secure actions such as logins, uploads and evaluations will appear here." />}</div>;
}

function FacultyQueryWorkspace() {
  const [queries, setQueries] = useState<QueryItem[]>([]); const [drafts, setDrafts] = useState<Record<string, string>>({});
  const load = () => apiFetch<QueryItem[]>("/api/v1/queries").then(setQueries).catch(() => setQueries([]));
  useEffect(() => { load(); }, []);
  const reply = async (query: QueryItem) => { const answer = drafts[query.id]?.trim(); if (!answer) return; await apiFetch(`/api/v1/queries/${query.id}/reply`, { method: "POST", body: JSON.stringify({ answer }) }); setDrafts((current) => ({ ...current, [query.id]: "" })); await load(); };
  return <div className="dashboard-card generic-list"><div className="section-kicker">Faculty queue</div><h2>Student queries</h2>{queries.length ? queries.map((query) => <article className="generic-row" key={query.id}><div className="generic-row-icon"><Icon name="message-circle" size={17} /></div><div><strong>{query.title}</strong><small>{query.subject} · {query.body}{query.answer ? ` · Reply: ${query.answer}` : ""}</small></div>{query.status !== "answered" ? <div className="paper-evaluate-inline"><input placeholder="Write a reply" value={drafts[query.id] ?? ""} onChange={(event) => setDrafts((current) => ({ ...current, [query.id]: event.target.value }))} /><button className="button button-soft" onClick={() => reply(query)}>Reply</button></div> : <span>{query.status}</span>}</article>) : <EmptyState icon="message-circle" title="No assigned queries." body="New student doubts will appear here." />}</div>;
}

function AdminWorkspace({ routeKey }: { routeKey: string }) {
  const [file, setFile] = useState<File | null>(null); const [form, setForm] = useState({ title: "", level: "CA Intermediate", subject: "Advanced Accounting", chapter: "", resource_type: "Study Material", attempt: "May 2027" }); const [status, setStatus] = useState<string | null>(null); const [uploading, setUploading] = useState(false);
  const isResourceManager = routeKey === "admin/resources" || routeKey === "admin";
  if (routeKey === "admin/mcqs") return <AdminMcqManager />;
  if (routeKey === "admin/tests") return <AdminTestManager />;
  if (routeKey === "admin/content") return <AdminContentManager />;
  if (routeKey === "admin/evaluations") return <PaperWorkspace mode="admin" />;
  if (routeKey === "admin/students") return <AdminUsersWorkspace role="student" />;
  if (routeKey === "admin/faculty") return <AdminUsersWorkspace role="faculty" />;
  if (routeKey === "admin/audit-logs") return <AuditLogsWorkspace />;
  if (routeKey === "admin/settings") return <AccountWorkspace settings />;
  async function upload(event: React.FormEvent) { event.preventDefault(); setStatus(null); setUploading(true); const body = new FormData(); Object.entries(form).forEach(([key, value]) => body.append(key, value)); if (file) body.append("file", file); try { const response = await fetch(`${API_BASE_URL}/api/v1/resources/upload`, { method: "POST", credentials: "include", body }); if (!response.ok) { const data = await response.json().catch(() => ({})); throw new Error(data.detail ?? "Upload failed"); } setStatus("Resource uploaded and available in the student library."); setForm((current) => ({ ...current, title: "" })); setFile(null); } catch (error) { setStatus(error instanceof Error ? error.message : "Upload failed. Check administrator access."); } finally { setUploading(false); } }
  if (!isResourceManager) return <AdminOverview />;
  return <div className="admin-manager-layout"><section className="dashboard-card upload-card"><div className="section-kicker">Content management</div><h2>Upload an authorised resource.</h2><p>Only upload material you are permitted to distribute. Files are validated and stored outside the public web root.</p><form className="admin-upload-form" onSubmit={upload}><label>Resource title<input value={form.title} onChange={(event) => setForm({ ...form, title: event.target.value })} placeholder="e.g. RTP · Advanced Accounting · May 2027" required /></label><div className="admin-two-col"><label>Level<select value={form.level} onChange={(event) => setForm({ ...form, level: event.target.value })}><option>CA Foundation</option><option>CA Intermediate</option><option>CA Final</option></select></label><label>Subject<input value={form.subject} onChange={(event) => setForm({ ...form, subject: event.target.value })} required /></label></div><label>Chapter<input value={form.chapter} onChange={(event) => setForm({ ...form, chapter: event.target.value })} placeholder="e.g. Consolidated Financial Statements" required /></label><div className="admin-two-col"><label>Resource type<select value={form.resource_type} onChange={(event) => setForm({ ...form, resource_type: event.target.value })}><option>Study Material</option><option>RTP</option><option>MTP</option><option>PYQ</option><option>Suggested Answer</option><option>Notes</option><option>Amendment</option><option>Question Bank</option></select></label><label>Attempt<input value={form.attempt} onChange={(event) => setForm({ ...form, attempt: event.target.value })} /></label></div><label className="file-drop"><input type="file" accept=".pdf,.png,.jpg,.jpeg,.webp,.doc,.docx,.xls,.xlsx" onChange={(event) => setFile(event.target.files?.[0] ?? null)} /> <Icon name="upload" size={20} /><strong>{file ? file.name : "Choose a file"}</strong><small>PDF, image, Word or Excel · max 15 MB</small></label>{status ? <div className="inline-notice"><Icon name="check" size={15} /> {status}</div> : null}<button className="button button-primary" type="submit" disabled={uploading}>{uploading ? "Uploading securely…" : "Upload resource"}<Icon name="arrow-up-right" size={14} /></button></form></section><aside className="admin-side-stack"><div className="dashboard-card admin-stat-card"><span className="section-kicker">Content health</span><strong>Ready to publish</strong><p>Every upload should carry level, subject, attempt and source metadata.</p></div><div className="dashboard-card admin-stat-card"><span className="section-kicker">Admin areas</span><Link href="/admin/students">Manage students <Icon name="arrow-right" size={14} /></Link><Link href="/admin/faculty">Manage faculty <Icon name="arrow-right" size={14} /></Link><Link href="/admin/audit-logs">Review audit logs <Icon name="arrow-right" size={14} /></Link></div></aside></div>;
}

function AdminOverview() { return <div className="admin-overview"><div className="admin-metric-grid">{[["Students", "0", "Live accounts"], ["Resources", "0", "Published items"], ["Pending queries", "0", "Need attention"], ["Evaluations", "0", "In the queue"]].map(([label, value, detail]) => <article className="metric-card metric-violet" key={label}><div className="metric-top"><span>{label}</span><Icon name="arrow-up-right" size={14} /></div><div className="metric-value-row"><strong>{value}</strong></div><div className="metric-bottom"><span>{detail}</span></div></article>)}</div><div className="admin-quick-grid"><Link href="/admin/resources" className="dashboard-card admin-quick-card"><Icon name="upload" size={20} /><div><span className="section-kicker">Content</span><h2>Upload resources</h2><p>Publish authorised study material for students.</p></div><Icon name="arrow-right" size={15} /></Link><Link href="/admin/mcqs" className="dashboard-card admin-quick-card"><Icon name="circle-help" size={20} /><div><span className="section-kicker">Practice</span><h2>Manage MCQs</h2><p>Create question banks for each subject.</p></div><Icon name="arrow-right" size={15} /></Link><Link href="/admin/announcements" className="dashboard-card admin-quick-card"><Icon name="bell" size={20} /><div><span className="section-kicker">Communication</span><h2>Announcements</h2><p>Keep students informed without clutter.</p></div><Icon name="arrow-right" size={15} /></Link></div></div>; }

type PaperItem = { id: string; title: string; subject: string; file_name?: string | null; annotated_file_name?: string | null; status: string; marks?: number | null; feedback?: string | null; assigned_to?: string | null; created_at: string; evaluated_at?: string | null };

function PaperWorkspace({ mode }: { mode: "student" | "faculty" | "admin" }) {
  const [papers, setPapers] = useState<PaperItem[]>([]); const [reviewing, setReviewing] = useState<PaperItem | null>(null); const [faculty, setFaculty] = useState<AdminUserItem[]>([]); const [assignees, setAssignees] = useState<Record<string, string>>({}); const [title, setTitle] = useState(""); const [subject, setSubject] = useState("Advanced Accounting"); const [file, setFile] = useState<File | null>(null); const [status, setStatus] = useState<string | null>(null);
  const load = () => apiFetch<PaperItem[]>("/api/v1/papers").then(setPapers).catch(() => setPapers([]));
  useEffect(() => { load(); if (mode === "admin") apiFetch<AdminUserItem[]>("/api/v1/admin/users?role=faculty").then(setFaculty).catch(() => setFaculty([])); }, [mode]);
  const submitPaper = async (event: React.FormEvent) => { event.preventDefault(); if (!file) return; const body = new FormData(); body.append("title", title); body.append("subject", subject); body.append("file", file); try { await apiFetch("/api/v1/papers/upload", { method: "POST", body }); setStatus("Paper submitted for evaluation."); setTitle(""); setFile(null); await load(); } catch (error) { setStatus(error instanceof ApiError ? error.message : "Could not submit paper."); } };
  const assign = async (paper: PaperItem) => { const facultyId = assignees[paper.id] ?? paper.assigned_to; if (!facultyId) return; try { await apiFetch(`/api/v1/papers/${paper.id}/assign`, { method: "PATCH", body: JSON.stringify({ faculty_id: facultyId }) }); setStatus("Paper assigned to faculty."); await load(); } catch (error) { setStatus(error instanceof ApiError ? error.message : "Could not assign paper."); } };
  return <div className="paper-workspace">{reviewing && mode !== "student" ? <PdfReviewEditor paperId={reviewing.id} title={reviewing.title} onClose={() => setReviewing(null)} onSaved={() => { setReviewing(null); load(); }} /> : null}{mode === "student" ? <section className="dashboard-card upload-card"><div className="section-kicker">Paper evaluation</div><h2>Submit an answer sheet.</h2><p>Upload an answer-sheet PDF for faculty feedback.</p><form className="admin-upload-form" onSubmit={submitPaper}><label>Paper title<input value={title} onChange={(event) => setTitle(event.target.value)} required /></label><label>Subject<input value={subject} onChange={(event) => setSubject(event.target.value)} required /></label><label className="file-drop"><input type="file" accept=".pdf,application/pdf" onChange={(event) => setFile(event.target.files?.[0] ?? null)} required /><Icon name="upload" size={20} /><strong>{file ? file.name : "Choose answer sheet"}</strong><small>PDF only · max 15 MB</small></label><button className="button button-primary">Submit for evaluation <Icon name="arrow-up-right" size={14} /></button></form></section> : null}<section className="dashboard-card generic-list"><div className="section-kicker">{mode === "student" ? "My submissions" : "Evaluation queue"}</div><h2>{papers.length} paper{papers.length === 1 ? "" : "s"}</h2>{papers.length ? papers.map((paper) => <article className="generic-row" key={paper.id}><div className="generic-row-icon"><Icon name="file-text" size={17} /></div><div><strong>{paper.title}</strong><small>{paper.subject} · {paper.status}{paper.marks !== null && paper.marks !== undefined ? ` · ${paper.marks} marks` : ""}{paper.feedback ? ` · ${paper.feedback}` : ""}</small></div>{mode === "admin" && paper.status !== "evaluated" ? <div className="paper-evaluate-inline"><select value={assignees[paper.id] ?? paper.assigned_to ?? ""} onChange={(event) => setAssignees((current) => ({ ...current, [paper.id]: event.target.value }))}><option value="">Assign faculty</option>{faculty.map((member) => <option key={member.id} value={member.id}>{member.full_name}</option>)}</select><button className="button button-soft" onClick={() => assign(paper)}>Assign</button></div> : null}{mode !== "student" && paper.file_name ? <button className="button button-soft" onClick={() => setReviewing(paper)}>{paper.status === "evaluated" ? "Open review" : "Review PDF"}<Icon name="file-text" size={14} /></button> : null}{paper.annotated_file_name ? <button className="text-button" onClick={() => window.open(`${API_BASE_URL}/api/v1/papers/${paper.id}/annotated-download`, "_blank", "noopener,noreferrer")}>Reviewed PDF <Icon name="arrow-up-right" size={14} /></button> : null}{mode === "student" && paper.file_name ? <button className="text-button" onClick={() => window.open(`${API_BASE_URL}/api/v1/papers/${paper.id}/download`, "_blank", "noopener,noreferrer")}>Submitted PDF <Icon name="arrow-up-right" size={14} /></button> : null}</article>) : <EmptyState icon="file-text" title="No papers in the queue." body={mode === "student" ? "Your submitted answer sheets will appear here." : "Assigned student papers will appear here."} />}</section>{status ? <div className="inline-notice"><Icon name="check" size={15} /> {status}</div> : null}</div>;
}

function FacultyWorkspace({ routeKey }: { routeKey: string }) {
  if (routeKey.endsWith("/papers")) return <PaperWorkspace mode="faculty" />;
  if (routeKey.endsWith("/queries")) return <FacultyQueryWorkspace />;
  if (routeKey.endsWith("/students")) return <FacultyStudentsWorkspace />;
  if (routeKey.endsWith("/tests")) return <TestsWorkspace />;
  if (routeKey.endsWith("/resources")) return <ResourceWorkspace />;
  if (routeKey.endsWith("/analytics")) return <AnalyticsWorkspace />;
  return <div className="faculty-overview"><AnalyticsWorkspace /><div className="dashboard-card empty-faculty"><div className="empty-state-icon"><Icon name="briefcase-business" size={22} /></div><h2>Your faculty queue will appear here.</h2><p>Evaluate assigned papers, reply to student queries and review preparation activity within your scope.</p><Link href="/faculty/papers" className="button button-primary">Open paper queue <Icon name="arrow-right" size={14} /></Link></div></div>;
}

export function FeatureWorkspace({ segments }: { segments: string[] }) {
  const routeKey = segments.join("/") || "dashboard";
  if (routeKey.startsWith("admin")) return <><FeatureHeader copy={{ eyebrow: "Admin workspace", title: routeKey === "admin" ? "Run the platform with clarity." : "Manage the right thing next.", body: "Students, content, permissions and audit history in one controlled workspace.", icon: "shield-check" }} action={routeKey === "admin/resources" ? undefined : "Upload resource"} onAction={() => window.location.assign("/admin/resources")} /><AdminWorkspace routeKey={routeKey} /></>;
  if (routeKey.startsWith("faculty")) return <><FeatureHeader copy={{ eyebrow: "Faculty workspace", title: "Feedback that moves students forward.", body: "Evaluate, reply and support only the cohorts assigned to you.", icon: "briefcase-business" }} /><FacultyWorkspace routeKey={routeKey} /></>;
  if (routeKey === "resources") return <><FeatureHeader copy={{ eyebrow: "Study resources", title: "A calmer way to find the right material.", body: "Browse authorised study material by level, subject, attempt and chapter.", icon: "book-open" }} /><ResourceWorkspace /></>;
  if (routeKey === "past-papers") return <><FeatureHeader copy={pageCopy["past-papers"]} /><ResourceWorkspace view="past-papers" /></>;
  if (routeKey === "library") return <><FeatureHeader copy={pageCopy.library} /><ResourceWorkspace view="library" /></>;
  if (routeKey === "notifications") return <><FeatureHeader copy={pageCopy.notifications} /><NotificationsWorkspace /></>;
  if (routeKey === "profile") return <><FeatureHeader copy={pageCopy.profile} /><AccountWorkspace /></>;
  if (routeKey === "settings") return <><FeatureHeader copy={pageCopy.settings} /><AccountWorkspace settings /></>;
  if (routeKey === "timetable") return <><FeatureHeader copy={pageCopy.timetable} /><TimetableWorkspace /></>;
  if (routeKey === "papers") return <><FeatureHeader copy={{ eyebrow: "Paper evaluation", title: "Submit work and learn from feedback.", body: "Upload an answer sheet and keep marks and faculty feedback with your attempt.", icon: "file-text" }} /><PaperWorkspace mode="student" /></>;
  const copy = pageCopy[segments[0]] ?? pageCopy[routeKey];
  if (segments[0] === "mcq") return <><FeatureHeader copy={copy} action="New practice" /><McqWorkspace /></>;
  if (segments[0] === "tests") return <><FeatureHeader copy={copy} action="Browse tests" /><TestsWorkspace /></>;
  if (segments[0] === "syllabus") return <><FeatureHeader copy={copy} /><SyllabusWorkspace /></>;
  if (segments[0] === "planner") return <><FeatureHeader copy={copy} action="Generate plan" /><PlannerWorkspace /></>;
  if (segments[0] === "revision") return <><FeatureHeader copy={copy} /><RevisionWorkspace /></>;
  if (segments[0] === "videos") return <><FeatureHeader copy={copy} /><VideosWorkspace /></>;
  if (segments[0] === "career" || segments[0] === "articleship") return <><FeatureHeader copy={copy} /><OpportunityWorkspace kind={segments[0]} /></>;
  if (segments[0] === "icai-updates") return <><FeatureHeader copy={copy} /><OfficialUpdatesWorkspace /></>;
  if (segments[0] === "ai") return <><FeatureHeader copy={copy} /><AIWorkspace /></>;
  if (segments[0] === "queries") return <><FeatureHeader copy={copy} action="Ask a doubt" /><QueriesWorkspace /></>;
  return <><FeatureHeader copy={copy ?? pageCopy.settings} /><GenericWorkspace routeKey={segments[0] ?? "settings"} /></>;
}
